import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang3.StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen2Test {











    @Test
    public void testJoin_WithNullElements() {
        Object[] array = {"a", null, "c"};
        // The logic: if (array[i] != null) { buf.append(array[i]); }
        // If array[i] is null, it just skips appending the content but still appends the separator if i > startIndex
        assertEquals("a,c", StringUtils.join(array, ",", 0, 3));

        Object[] arrayWithLeadingNull = {null, "b", "c"};
        assertEquals(",b,c", StringUtils.join(arrayWithLeadingNull, ",", 0, 3));

        Object[] arrayWithTrailingNull = {"a", "b", null};
        assertEquals("a,b,", StringUtils.join(arrayWithTrailingNull, ",", 0, 3));
    }






}

